"""Renders `contracts/openapi.yaml` from the app's routes."""

import yaml

from greenink_api.main import create_app

HEADER = (
    '# Frozen contract (SPEC "API contract"). Generated by `make openapi`; do not edit by hand.\n'
    "# Changing it needs a PR note and a regenerated web client.\n"
)


def render_openapi() -> str:
    spec = create_app().openapi()
    return HEADER + yaml.safe_dump(spec, sort_keys=False, allow_unicode=True, width=100)
